                    if s[i] == ',':
                        items.append(parse_value(s[i+1:i]))
                        i += 1
                    elif s[i] == ']':
                        break
                    else:
                        raise ValueError("Invalid JSON string: unexpected character in list")
                return items
            else:
                return []
        elif s[0] == '{':
            # Parse dictionary
            s = s[1:-1]
